', status = 'READY', answer_type = 'NAT', nat_min = 330, nat_max = 330, difficulty = 2, answer_status = 'UNVERIFIED', content_key = 'gate-2014-s1-6', origin = 'PYQ', updated_at = now() WHERE id = qid;
