', status = 'READY', answer_type = 'MCQ', nat_min = NULL, nat_max = NULL, difficulty = 2, answer_status = 'UNVERIFIED', content_key = 'gate-2014-s1-8', origin = 'PYQ', updated_at = now() WHERE id = qid;
