-- clean-up
DELETE FROM question_link l WHERE NOT EXISTS (SELECT 1 FROM question_source qs WHERE qs.question_id = l.gate_question_id) OR NOT EXISTS (SELECT 1 FROM question_source qs WHERE qs.question_id = l.state_question_id);
DELETE FROM question q WHERE q.origin = 'PYQ' AND NOT EXISTS (SELECT 1 FROM question_source qs WHERE qs.question_id = q.id) AND NOT EXISTS (SELECT 1 FROM attempt a WHERE a.question_id = q.id) AND NOT EXISTS (SELECT 1 FROM user_question_state u WHERE u.question_id = q.id) AND NOT EXISTS (SELECT 1 FROM test_question tq WHERE tq.question_id = q.id);
DELETE FROM topic t WHERE t.slug IN ('-373', '-344', '-355') AND NOT EXISTS (SELECT 1 FROM question x WHERE x.topic_id = t.id) AND NOT EXISTS (SELECT 1 FROM concept_section c WHERE c.topic_id = t.id) AND NOT EXISTS (SELECT 1 FROM syllabus_item_topic st WHERE st.topic_id = t.id);
DELETE FROM topic t WHERE t.subject_id = (SELECT id FROM subject WHERE slug = 'electric-circuits') AND t.slug IN ('ideal-sources-90', 'r-l-c-element-relations-v-ri-l-di-dt-42', 'power-in-resistive-loads-lamps-165', 'circuit-elements-nullator-linearity-363', 'nonlinear-resistance-195', 'nonlinear-resistor-circuits-251', 'equivalent-resistance-network-reduction-33', 'series-circuits-voltage-division-163') AND NOT EXISTS (SELECT 1 FROM question x WHERE x.topic_id = t.id) AND NOT EXISTS (SELECT 1 FROM concept_section c WHERE c.topic_id = t.id) AND NOT EXISTS (SELECT 1 FROM syllabus_item_topic st WHERE st.topic_id = t.id);
